CREATE OR REPLACE FUNCTION public.get_active_announcements(_lang text DEFAULT 'sv',_app_version text DEFAULT NULL) RETURNS TABLE(id uuid,kind text,priority integer,display_mode text,requires_ack boolean,dismissible boolean,content jsonb,style jsonb,ends_at timestamptz) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); BEGIN IF uid IS NULL THEN RETURN; END IF; RETURN QUERY SELECT a.id,a.kind,a.priority,a.display_mode,a.requires_ack,a.dismissible,coalesce(a.content->coalesce(_lang,'sv'),a.content->'sv'),a.style,a.ends_at FROM app_announcements a WHERE a.status IN ('scheduled','published') AND (a.starts_at IS NULL OR a.starts_at<=now()) AND (a.ends_at IS NULL OR a.ends_at>now()) AND public.app_version_gte(_app_version,a.min_app_version) AND public.campaign_audience_match(uid,a.targeting,_lang,false,a.kind IN ('important','maintenance','service_interruption','app_update')) AND NOT(a.display_mode='once_per_user' AND EXISTS(SELECT 1 FROM campaign_events e WHERE e.user_id=uid AND e.campaign_id=a.id AND (e.event IN ('dismissed','acknowledged') OR (e.event='displayed' AND NOT a.requires_ack)))) AND NOT(a.display_mode='until_dismissed' AND EXISTS(SELECT 1 FROM campaign_events e WHERE e.user_id=uid AND e.campaign_id=a.id AND e.event IN ('dismissed','acknowledged'))) AND NOT(a.requires_ack AND EXISTS(SELECT 1 FROM campaign_events e WHERE e.user_id=uid AND e.campaign_id=a.id AND e.event='acknowledged')) ORDER BY a.priority,a.starts_at NULLS LAST; END $$;
CREATE OR REPLACE FUNCTION public.get_native_advertisements(_lang text DEFAULT 'sv',_app_version text DEFAULT NULL) RETURNS TABLE(id uuid,sponsor_name text,template text,content jsonb,style jsonb,cta_url text,secondary_url text,max_per_day integer,min_minutes_between integer,max_total_per_user integer,once_per_campaign boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); BEGIN IF uid IS NULL THEN RETURN; END IF; RETURN QUERY SELECT d.id,d.sponsor_name,d.template,coalesce(d.content->coalesce(_lang,'sv'),d.content->'sv'),d.style,d.cta_url,d.secondary_url,d.max_per_day,d.min_minutes_between,d.max_total_per_user,d.once_per_campaign FROM app_advertisements d WHERE d.status IN ('scheduled','active') AND (d.starts_at IS NULL OR d.starts_at<=now()) AND (d.ends_at IS NULL OR d.ends_at>now()) AND public.app_version_gte(_app_version,d.min_app_version) AND public.campaign_audience_match(uid,d.targeting,_lang,true,false) AND (SELECT count(*) FROM campaign_events e WHERE e.user_id=uid AND e.campaign_id=d.id AND e.event='displayed' AND e.created_at>=date_trunc('day',now() AT TIME ZONE d.timezone) AT TIME ZONE d.timezone)<d.max_per_day AND NOT EXISTS(SELECT 1 FROM campaign_events e WHERE e.user_id=uid AND e.campaign_id=d.id AND e.event='displayed' AND e.created_at>now()-make_interval(mins=>d.min_minutes_between)) AND (d.max_total_per_user IS NULL OR (SELECT count(*) FROM campaign_events e WHERE e.user_id=uid AND e.campaign_id=d.id AND e.event='displayed')<d.max_total_per_user) AND NOT(d.once_per_campaign AND EXISTS(SELECT 1 FROM campaign_events e WHERE e.user_id=uid AND e.campaign_id=d.id AND e.event='displayed')) AND NOT EXISTS(SELECT 1 FROM campaign_events e WHERE e.user_id=uid AND e.campaign_type='advertisement' AND e.event='displayed' AND e.created_at>now()-interval '4 hours') ORDER BY d.priority,d.starts_at NULLS LAST LIMIT 1; END $$; REVOKE ALL ON FUNCTION public.get_native_advertisements(text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_native_advertisements(text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.record_campaign_event(_type text,_campaign_id uuid,_event text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); ok boolean; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Not signed in' USING ERRCODE='42501'; END IF; IF _event NOT IN ('eligible','displayed','dismissed','acknowledged','cta_click','secondary_click') THEN RAISE EXCEPTION 'Invalid event'; END IF; ok:=CASE _type WHEN 'announcement' THEN EXISTS(SELECT 1 FROM app_announcements WHERE id=_campaign_id AND status IN ('scheduled','published')) WHEN 'advertisement' THEN EXISTS(SELECT 1 FROM app_advertisements d WHERE d.id=_campaign_id AND d.status IN ('scheduled','active') AND public.campaign_audience_match(uid,d.targeting,NULL,true,false)) WHEN 'sponsored_challenge' THEN EXISTS(SELECT 1 FROM sponsored_challenges WHERE id=_campaign_id AND status IN ('visible','active','completed')) ELSE false END; IF NOT coalesce(ok,false) THEN RAISE EXCEPTION 'Campaign not available'; END IF; IF (SELECT count(*) FROM campaign_events WHERE user_id=uid AND created_at>now()-interval '1 minute')>=30 THEN RAISE EXCEPTION 'Too many events'; END IF; INSERT INTO campaign_events(campaign_type,campaign_id,user_id,event) VALUES(_type,_campaign_id,uid,_event); END $$;